//! Nocturne (夜航): a quiet navy dashboard with blue-violet accents.
use dotisle_domain::monet::Scheme;
use vello::{Scene,kurbo::{Affine,Rect},peniko::{Fill,Gradient}};
use crate::{draw::{self,rect,Icon},widgets::Ui,model::{Model,Action},views::{self,ViewState}};
pub fn active(m:&Model)->bool{m.prefs.control_center_theme=="Nocturne"}
pub fn scheme(dark:bool)->Scheme{if dark{Scheme{
 primary:0x70A5FF,on_primary:0x07172F,primary_container:0x142037,on_primary_container:0xF0F5FF,secondary_container:0x1D3155,on_secondary_container:0xE3EDFF,tertiary_container:0x1D2340,on_tertiary_container:0xF0F2FF,surface:0x0B0F1A,container:0x131B2B,high:0x1B263A,on_surface:0xF9FAFB,on_surface_variant:0xA9B6CC,outline:0x62728C,outline_variant:0x2A3951,error:0xFFA5AF,
}}else{Scheme{
 primary:0x285EC4,on_primary:0xFFFFFF,primary_container:0xEDF3FE,on_primary_container:0x15233D,secondary_container:0xDBE8FF,on_secondary_container:0x153B77,tertiary_container:0xF0EDFC,on_tertiary_container:0x2F2856,surface:0xF3F6FC,container:0xFFFFFF,high:0xE8EDF6,on_surface:0x18243A,on_surface_variant:0x586B87,outline:0x7B8CA6,outline_variant:0xCFD9EA,error:0xB52B49,
}}}
pub fn accent(scene:&mut Scene,r:Rect,radius:f64){let gradient=Gradient::new_linear((r.x0,r.y0),(r.x1,r.y1)).with_stops([draw::color(0x3069D7),draw::color(0x6A4FD3)]);scene.fill(Fill::NonZero,Affine::IDENTITY,&gradient,None,&dotisle_render::draw::continuous_rect(r,radius));}
pub fn panel(scene:&mut Scene,r:Rect,bg:u32,edge:u32){draw::fill(scene,r,18.,bg);draw::outline(scene,r,18.,edge,1.);}
pub fn header(ui:&mut Ui,m:&Model,x:f64,w:f64){let s=ui.s;accent(ui.scene,rect(x,166.,48.,3.),1.5);let right=x+w-318.;for(i,(title,value))in [("待办",format!("{} 件",m.pending())),("桌面组件",format!("{} 个",m.desktop_widgets.items.len()))].into_iter().enumerate(){let cx=right+i as f64*166.;ui.label(title,cx,91.,11.,s.on_surface_variant,false,140.);ui.label(&value,cx,111.,23.,s.on_surface,true,140.);draw::line(ui.scene,(cx-16.,95.),(cx-16.,142.),s.outline_variant,1.);}}
pub fn music_card(ui:&mut Ui,m:&Model,w:f64,h:f64,state:&ViewState){let s=ui.s;views::record(ui,m,rect(26.,67.,132.,132.),false);ui.label(if m.playing(){"正在播放"}else if m.track(){"已暂停"}else{"等待播放器"},26.,215.,12.,if m.playing(){if s.surface<0x808080{0x86DBB3}else{0x246E4E}}else{s.on_surface_variant},true,132.);let px=184.;let avail=w-px-26.;ui.label(m.title(),px,69.,30.,s.on_primary_container,true,avail);ui.label(m.artist(),px,113.,14.,s.on_surface_variant,false,avail);ui.label(m.current_lyric(),px,146.,14.,s.on_primary_container,false,avail);views::player_controls(ui,m,px-6.,179.,false);views::progress(ui,m,rect(px+226.,181.,(avail-226.).max(100.),24.),state);ui.label("歌词同步",26.,h-35.,11.,s.on_surface_variant,false,66.);ui.icon_button(rect(98.,h-46.,36.,36.),Icon::Back,"歌词提前 100 毫秒",Action::Offset(-100),false,true);ui.center(&format!("{:+} ms",m.prefs.offset_ms),rect(138.,h-46.,88.,36.),12.,s.on_primary_container,true);ui.icon_button(rect(230.,h-46.,36.,36.),Icon::Arrow,"歌词延后 100 毫秒",Action::Offset(100),false,true);ui.button(rect(w-208.,h-48.,184.,36.),"布局与播放组件",Some(Icon::Settings),Action::LayoutOpen,true,true);}
